4px}.health-track i{display:block;height:100%;width:100%;background:#a5d9ad;border-radius:4px;transition:width .2s}.health-value{text-align:right}.health-value strong{font:500 18px 'DM Mono',monospace}.health-value small{display:block;font:7px 'DM Mono',monospace;color:#9fb3ab;letter-spacing:1px}.minimap{position:absolute;right:30px;bottom:31px;width:198px;padding:11px 11px 8px}.mini-head,.map-foot{display:flex;justify-content:space-between;align-items:center;font:500 8px 'DM Mono',monospace;letter-spacing:1px;color:#c6d3ca}.mini-head span:last-child{color:#e8bc83}.minimap canvas{display:block;width:174px;height:136px;margin:8px auto 5px;border-radius:6px;background:rgba(7,19,20,.36)}.map-foot{justify-content:flex-start;gap:15px;font-size:7px;color:#aabbb2}.map-foot i{display:inline-block;width:6px;height:6px;border-radius:50%;margin-right:4px}.legend-player{background:#e9cf9a}.legend-threat{background:#ff7268}.weapon-chip{position:absolute;bottom:33px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;padding:8px 11px;min-width:195px}.weapon-icon{font-size:24px;color:#edc590}.weapon-chip b{display:block;font:500 9px 'DM Mono',monospace;letter-spacing:.8px}.weapon-chip small{display:block;font:7px 'DM Mono',monospace;color:#a8bbb3;letter-spacing:.6px;margin-top:3px}.weapon-chip kbd{margin-left:auto;border:1px solid rgba(236,245,232,.2);padding:4px 6px;border-radius:4px;font:8px 'DM Mono',monospace;color:#d4d8c8}.help-pill{position:absolute;left:50%;bottom:120px;transform:translateX(-50%);padding:9px 13px;border-radius:8px;font:500 8px 'DM Mono',monospace;letter-spacing:.6px;color:#d5dfd8;white-space:nowrap;transition:opacity .4s}.help-pill span{color:#f0d09a}.help-pill i{font-style:normal;color:#789089;margin:0 4px}.help-pill button{border:0;background:none;color:#b9c9c0;font-size:14px;margin-left:8px;cursor:pointer}.crosshair{position:absolute;left:50%;top:50%;width:25px;height:25px;transform:translate(-50%,-50%);opacity:.83;pointer-events:none;transition:opacity .2s}.crosshair i{position:absolute;background:rgba(255,243,216,.9);box-shadow:0 0 4px #182827}.crosshair i:nth-child(1){width:1px;height:5px;left:12px;top:0}.crosshair i:nth-child(2){width:1px;height:5px;left:12px;bottom:0}.crosshair i:nth-child(3){height:1px;width:5px;left:0;top:12px}.crosshair i:nth-child(4){height:1px;width:5px;right:0;top:12px}.crosshair b{position:absolute;width:3px;height:3px;border:1px solid #fff4d8;border-radius:50%;left:11px;top:11px}.objective-toast{position:absolute;top:20%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.4s;text-align:center;padding:12px 24px;border:1px solid rgba(238,207,157,.45);border-radius:9px;background:rgba(20,36,35,.76);backdrop-filter:blur(10px);pointer-events:none}.objective-toast.show{opacity:1;transform:translate(-50%,0)}.objective-toast span{color:#e8bc83;margin-right:8px}.objective-toast b{font:500 10px 'DM Mono',monospace;letter-spacing:1.2px}.objective-toast small{display:block;color:#b4c7bd;font-size:9px;margin-top:5px}.pause-overlay{position:absolute;inset:0;background:rgba(8,18,18,.43);display:grid;place-items:center;opacity:0;pointer-events:none;transition:opacity .25s}.pause-overlay.show{opacity:1;pointer-events:auto}.pause-panel{padding:30px 36px;text-align:center;width:min(340px,90vw)}.pause-panel h2{font-size:30px;letter-spacing:4px;margin:15px 0 4px}.pause-panel p{font-size:12px;color:#b4c5bd;margin:0 0 22px}.primary-button{background:#e9bf88;border:0;border-radius:7px;padding:12px 17px;color:#23302c;font-size:10px;font-weight:800;letter-spacing:1px;cursor:pointer;width:100%}.primary-button span{float:right}.loading{position:absolute;inset:0;z-index:8;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:14px;background:#182528;transition:opacity .6s}.loading.done{opacity:0;pointer-events:none}.loader-mark{width:55px;height:55px;font-size:21px}.loading>span{font:9px 'DM Mono',monospace;letter-spacing:2px;color:#a8beb3}.loading-line{width:150px;height:2px;background:#40504c}.loading-line i{display:block;height:100%;width:0;background:#e8bc83;animation:load 1.4s ease forwards}@keyframes load{to{width:100%}}.toast-feed{position:absolute;right:250px;top:100px;display:flex;flex-direction:column;gap:6px;pointer-events:none}.feed-item{border-left:2px solid #e8bc83;background:rgba(17,29,30,.78);padding:8px 11px;font:8px 'DM Mono',monospace;letter-spacing:.6px;animation:feedin .25s ease}.feed-item span{color:#e8bc83;margin-right:6px}@keyframes feedin{from{opacity:0;transform:translateX(10px)}to{opacity:1;transform:translateX(0)}}.boss-banner{position:absolute;display:none;left:50%;top:18px;transform:translateX(-50%);width:min(390px,80vw);text-align:center}.boss-banner.show{display:block}.boss-label{font:500 10px 'DM Mono',monospace;color:#ffb48c;letter-spacing:1px;text-shadow:0 2px 6px #162}.boss-label span{font-size:7px;color:#f0d9ca;margin-left:8px}.boss-track{height:5px;background:rgba(20,20,20,.6);margin-top:8px;border-radius:8px;overflow:hidden;border:1px solid rgba(255,225,199,.3)}.boss-track i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#e06d61,#f5b773);transition:width .2s}.damage-flash{position:absolute;inset:0;border:0 solid rgba(239,68,57,0);pointer-events:none}.damage-flash.hit{animation:damage .35s ease}@keyframes damage{0%{box-shadow:inset 0 0 0 0 rgba(245,72,54,.4)}40%{box-shadow:inset 0 0 90px 20px rgba(245,72,54,.25)}100%{box-shadow:inset 0 0 0 0 rgba(245,72,54,0)}}.mobile-controls{display:none}.stick-zone{position:absolute;bottom:24px;left:20px;width:132px;height:132px;touch-action:none}.stick-base{position:absolute;inset:13px;border:1px solid rgba(255,255,255,.36);border-radius:50%;background:rgba(15,28,30,.31);backdrop-filter:blur(5px);box-shadow:inset 0 0 20px rgba(255,255,255,.06)}.stick-knob{position:absolute;left:50%;top:50%;width:48px;height:48px;transform:translate(-50%,-50%);border-radius:50%;background:rgba(238,211,167,.73);border:1px solid rgba(255,255,255,.7);box-shadow:0 3px 12px #1126}.mobile-actions{position:absolute;right:18px;bottom:20px;width:163px;height:151px}.touch-button{position:absolute;width:56px;height:56px;border:1px solid rgba(255,255,255,.45);border-radius:50%;background:rgba(18,33,34,.55);backdrop-filter:blur(6px);display:flex;flex-direction:column;justify-content:center;align-items:center;gap:0;touch-action:none}.touch-button span{font-size:19px;line-height:20px;color:#f0d19e}.touch-button small{font:7px 'DM Mono',monospace;letter-spacing:.5px}.fire-button{right:4px;top:43px;background:rgba(164,78,60,.55)}.drive-button{right:56px;top:0}.enter-button{right:0;top:0}.boost-button{right:56px;top:94px}.boss-banner.show~.mobile-controls{display:block}
