@media(max-width:390px){.mission-card{width:calc(100vw - 150px);min-width:205px}.mission-state{display:none}.minimap{width:116px}.minimap canvas{width:98px;height:75px}.mission-foot span{font-size:5.5px}.topbar{padding:9px}.brand-name{font-size:10px}.top-actions{gap:3px}.icon-button{padding:0 6px}}
